INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1538666-bus200', 'stk-idk', 'BUS 200', 'info', '{"desc": "T241\n\nجودة المقرر بشكل عام:\nالمقرر سهل جدا وممتع صراحة ومن أكثر الكورسات الي كنت مستمتع فيها وما تحتاج تركز مع الدكتور مرا عشان تكون فاهم الدروس لان الدروس واضحة واذا مافي شي واضح تقدر تسأل تشات يساعدك ويفهمك النقطة الي منت فاهمها\n\nالمواضيع التي يغطيها المقرر:\n\nChapter NumberChapter TopicChapter NumberChapter TopicCH01Teamwork in BusinessCH07Entrepreneurship and Small BusinessCH02The Foundations of BusinessCH08Management and LeadershipCH03Economics and BusinessCH10Operations ManagementCH04Ethics and Social ResponsibilityCH14Marketing: Providing Value to CustomersCH05Business in a Global EnvironmentCH17Accounting and Financial Information\n\nالكتاب المستخدم للمقرر:\nFundamentals of Business 4th edition\nكتاب خفيف واللغة المستخدمة فيه ماهي صعبة\n\nتوزيع الدرجات:\nimage809×431 38.5 KB\n\nنصائح للكورس:\nالكورس ماهو صعب على حظنا ماكان فيه أية كويزات وكان صراحة توزيع الدرجات جدا ممتاز ومافيه اية ظلم\nالكورس فيه ميد وفاينل فقط ولكن الكورس يعتمد على القروب للي معك يعني يمكن تلاقي شخص ماخذ كامل بالميد والفاينل ولكن طبيعي انه ما يجيب A+\nاختار دكتور كويس لان زي ما قلت الدكتور ماراح يأثر مرا في فهمك للمادة لكن تحتاج دكتور تصحيحه كويس وواضح في طريقة تصحيحه ويكون عادل طبعا الدكاترة الي يدرسون ذا الكورس اغلبهم كويسين ولكن اكيد فيه واحد اثنين مخربينه على الطلاب\nاختار قروب كويس حاول تاخذ ذا الكورس مع ناس تعرفهم وحتى لو ما اخذته مع ناس تعرفهم حاول بقدر الامكان تدور لك ناس شغيلة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bus200-business-entrepreneurship/185047/3", "user": "idk", "ts": 1735760357498, "tid": 185047, "pn": 3}}', 1735760357498, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-bus200', 'stk-idk', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f98419", "n": "Dr. Muhammad Shahidulislam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BUS200 - T241\n\nالتحضير :\nرهيب بالتحضير ما عنده مشكلة, اذا تبغا دكتور متساهل بالتحضير فنزل عنده\n\nطريقة الشرح :\nمن سلايدات القسم, شرحه عادي بس مو ممل, نظامه يقرا من السلايدات وبعدين يشرح, الحلو انه ما يهتم اذا الطالب مركز معه بالكلاس او لا\n\nالكويزات :\nمافي كويزات\n\nالمياجر:\nكومن (بس كان افرج كلاساته تقريبا 21.5 من 25)\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح\n\nإضافات :\nدكتور حبيب ولطيف قديم بالجامعة, تصححيه بعد كويس بس يدقق على خفيف بس متعاون اذا الطالب عنده سؤال او اي شي نصيحتي للي بينزل عنده قبل ما تسلم واجب او اي شي وره شغلك واساله اذا كويس أو لا وبس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537878-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-shahidulislam/98419/22", "user": "idk", "ts": 1730824153659, "tid": 98419, "pn": 22}}]}', 1730824153659, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-bus200', 'stk-moh_ammed', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f98441", "n": "Dr. Ehab Qahwash", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BUS 200 - Term 221\n\nالتحضير: ينادي بالأسماء وغالبا ماعنده مشكلة مع التأخير.\n\nالشرح: جيد.\n\nالكويزات: فيه 4 كويزات وكنا ناخذهم على البلاكبورد…خيارات وصح خطأ، مستواهم مب صعب، إذا ماقدرت تذاكر الكتاب ذاكر السلايدات على الأقل وغالبا بتكفيك إنك تجيب فل خصوصا إذا كنت دايم تركز مع شرح الدكتور في المحاضرات، بس أنا أنصحك تذاكر الكتاب عشان إذا جاء وقت الميد أو الفاينل تكون مذاكر وتحتاج مراجعة فقط، ولكن إذا ماعندك وقت مايمنع إنك تذاكر السلايدات.\n\nإضافات:\n* الدكتور بصراحة عسل ويفتح النفس وخفيف دم الله يوفقه.\n* في بداية الترم تفاجأنا إن مبنى الكلاس تغير وصار بعيد على كثير من الطلاب، فالدكتور - جزاه الله خير - صار يبدأ المحاضرة بعد 5-10 دقايق تقريبا من بدايتها.\n* الدكتور يحاول يساعد الطلاب قد مايقدر بس المشكلة إن كثير من الأمور في الكورس موحدة لكل الدكاترة (ومنها موعد الكويزات) فما كان يقدر يتساعد معنا دايم.\n\nالدكتور ممتاز عموما…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536121-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ehab-qahwash/98441/47", "user": "Moh_ammed", "ts": 1673029151000, "tid": 98441, "pn": 47}}]}', 1673029151000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-bus200', 'stk-yousef_alamoudi_4507', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f98479", "n": "Dr. Sami Abdallah Alwuhaibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BUS200 - Term 211\n\nالتحضير: جت فترة بداية الترم يحضر بداية الكلاس، بس خلال نص الترم الى اخره صار نهاية الكلاس يحضر.\n\nطريقة الشرح: من سلايداته و يوضح في السبورة بعض الاحيان.\n\nالكويزات: 4 كومن كانت لجميع سكاشن المادة (سهلة و بسيطة جدا 4 اسئلة MCQ لكل ك)\n\nالميد: كومن و كان متوسط مائل للسهولة.\n\nالفاينل: كومن و الله ييسره نشوف كيف يكون.\n\nالقريد النهائي : S+ و قليلة بحقه (S+ > +A).\n\nالصوت: واضح جدا.\n\nإضافات: الدكتور اخلاق و حبوب و متعاون ما شاء الله علي، يهتم لمصلحة الطالب بشكل مو طبيعي يبغاك منجد تتعلم شيء راح تطبقه في المستقبل، يحب يعمل نشاطات خصوصا بداية الترم كان مكثر منها شوي، منجد دكتور ما اقدر اوفي حقه، نصيحتي انك حاول تشارك معاه و تبين انك مهتم و متفاعل راح يساعدك كثير ذا الموضوع.\n\nبالنسبة للبونصات اعطى نشاطين ( اما درجتين لكل واحد او درجة و نص)، النشاط الاول كان حضور محاضرة ليلية (لقاء بكل بساطة) و الثاني هو انك تتفرج على مقطع يوتيوب عن ريادة الاعمال و تعطي ملخص له و ايش اللي تعلمته.\n\nلو لقيته مرة ثانية في مادة اخرى في البزنس راح انزل و انا مغمض، انصح بيه و بقوة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533137-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sami-abdallah-alwuhaibi/98479/11", "user": "yousef_Alamoudi_4507", "ts": 1640179300000, "tid": 98479, "pn": 11}}]}', 1640179300000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeroal-bus200', 'stk-zeroal', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f98479", "n": "Dr. Sami Abdallah Alwuhaibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Bus200-Term211\n\nالتحضير :يحضر نهاية الكلاس وبعض الاحيان ينسى وما يقول شي عالتأخير.\nطريقة الشرح :يفتح السلايدات ويشرح, اغلب شرحه من خبرته وتجاربه تستفيد منه كثير من هالناحية. ويهتم جدآ انك تفهم اللي تدرسه عالوقع وهل هو اللي فعلآ قاعد يصير.\nالكويزات : كومن. سهلة جدآ الكتاب كافي.\nالمياجر: مافي مياجر فيه مد وكومن. أيضآ سهل والكتاب كافي بس مع فهم اللي انت تقراه.\nالفاينلات : نفس المد(ماتيريال المد غير ماتيريال الفاينال)\nالصوت:,واضح\nالقريد النهائي:A+\nإضافات :ثاني اسبوع بيقولكم يالله وزعو تيماتكم بيحصل حوسة شوي بس رح مع التيم اللي تبيه وبيكون حلو لو قدرت تسجل مع واحد تعرفه بنفس الشعبة.\nعمومآ المادة سهلة وممتعة فيها مشروعين 1-تقابلون صاحب مشروع او رائد أعمال وتسوون ريبورت وبرزنتيشن. 2-تجيب فكرة بزنس وتشرحها (فيها ريبورت وبرزنتيشن). لا تضغطون على ارواحكم وحاولو تخلصون بدري.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533176-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sami-abdallah-alwuhaibi/98479/12", "user": "zeroal", "ts": 1640530141000, "tid": 98479, "pn": 12}}]}', 1640530141000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jolenve-bus200', 'stk-jolenve', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f98479", "n": "Dr. Sami Abdallah Alwuhaibi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Bus200-Term212\n\nالتحضير :يحضر نهاية الكلاس وبعض الاحيان ينسى وما يقول شي عالتأخير.\nطريقة الشرح :يفتح السلايدات ويشرح, اغلب شرحه من خبرته وتجاربه تستفيد منه كثير من هالناحية. ويهتم جدآ انك تفهم اللي تدرسه عالوقع وهل هو اللي فعلآ قاعد يصير.\nالكويزات : كومن. سهلة جدآ الكتاب كافي.\nالمياجر: مافي مياجر فيه مد وكومن. ملخصات 2am ممتازة جدا\nالفاينلات : نفس المد\nالصوت:,واضح\nالقريد النهائي:A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534473-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-sami-abdallah-alwuhaibi/98479/13", "user": "Jolenve", "ts": 1653650826000, "tid": 98479, "pn": 13}}]}', 1653650826000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_exceptional_stude-bus200', 'stk-mr_exceptional_stude', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f118970", "n": "Dr. Maxwell Heineck", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Bus-200 term 212\n\nالتحضير : يحضر بالعادة بوسط اللكشر، يعطيك 6 غيابات مجاناً (الـ20% من الكلاسات الي قبل الـDN مجاناً) وأكثر من مرة يكنسل كلاس\nطريقة الشرح : دكتور رائع وتجربته وخبرته متقدمة وطريقة شرحه ممتعة وواضحة، هو غالباً أفضل دكتور للمادة سواءً بالشرح أو عموماً.\nالكويزات : كويزات مستواها سهل إلى متوسط ولو تذاكر السلايدات بس تحل 70-80% منها برايي فتحتاج تذاكر الكتاب، ولكن تفيدك ذا المذاكرة للميد والفاينل مرة وحدة.\nالمياجر: كومن (ميد)\nالفاينلات : كومن\nالقريد النهائي: +A\nالصوت: واضح جداً\nإضافات : أفضل دكتور ممكن تنزل عنده هالمادة، وممكن يكون أفضل دكتور يمر عليك بالجامعة؛ لأن حتى تعامله حلو. طبعاً ما يجامل بالتصحيح، ممكن تنقص إذا ما أعطيت الآساينمنت حقه لكن لو سويت زي ما يبي بسهولة تاخذ +A. طبعاً المادة ستاندرد (ممكن تقلب كيرف حسب الكوردنيتر).\n\nإضافة: هالدرايف مفيد جداً للمادة وشامل لكل مصادرها للي بياخذها:\nOmar’s BUS-200 Drive @ KFUPM - Google Drive", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534393-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/maxwell-heineck/118970/26", "user": "Mr_Exceptional_Stude", "ts": 1653314252000, "tid": 118970, "pn": 26}}]}', 1653314252000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-bus200', 'stk-user12137', 'BUS 200', 'doc', '{"docs": [{"id": "stk-dr-f172139", "n": "Dr. Mohammed Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BUS200-T231\n\nالتحضير: يحضر بعد بدأ الكلاس ب3 دقائق تقريبا وإذا تأخرت جيت بعدما خلص بيحسب عليك تأخير\n\nطريقة الشرح : شرحه ممتاز وواضح وبدون تكرار وحشو فاضي وإذا في جزئية مهمة ما هي بالسلايدات وتجي غالبا في الميد والفاينل بيغطيها عن طريق أنه يفتح الكتاب, وأمثلته عصرية ومن الواقع ما يجيب شيء من العصر الحجري بما أنه قريب لعمرنا شباب, والدكتور ينكت أثناء الشرح وحلوة نكاته تهكمية غالبا تكون وتلطف الجو, متفاعل بقوة في التييمز وما يحب الايميل فاسأله في التييمز اذا ما فهمت شيء\n\nالكويزات:\nسهلة جدا ترو فولس, وكل كويز تشابترين فلو تذاكر قبل الكلاس لمدة 15 دقيقة بتجيب فوق ال8 من 10 غالبا ,وحتى لو ما ذاكرت وبس من ذاكرتك بتجيب عدل\n\nالميد:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nB+\nالصوت:\nواضح\n\nإضافات :\n-الدكتور ذكي ويعرف ينتقد الأفكار والحلول الي تطرحها بشكل جيد جدا, كنت أفكر بنقول أي كلام وشغل أبو حيو وبيسلك لينا بس عنده ضمير طلع , فأحيانا تكون غثيثة السالفة أنت تبغى تمشي الوضع ومادة قريد بس هو يدقق لك, ولكن أكيد هالشيء بيفهمك بشكل أفضل للميتيريال مو من جانب دراسي وفقط بل حتى حياتي, لما اقرأ في الاقتصاد أو الأسهم أشوف أن المفاهيم تكون علي سهلة لأني صرت أعرفها بشكل أكبر من تدقيقه علينا\n\n-من ناحية الدرجات ما يمشي بيعطيك الدرجة الي تستاهلها فعلا, ما بيجحف بحقك ولا بيزيد لك. بس اذا بيميل فبيميل اتجاه الزيادة بشكل طفيف\n\n-شخصية الدكتور (نقطة غير مهمة): الدكتور باقرب لك شخصيته عن طريق سالفتين قالهم\nالسالفة الاولى: يقول لنا أن في طالب جاه بالتييمز وقال له “صباح الخير” بس كذا كأنه خويه بدون ما يسأل عن شيء وما عجبه تصرفه فما رد عليه, وجاه واحد ثاني وبدون أي تحية ورسل له التاسك عشان يقيمه ورد عليه\nالسالفة الثانية: هو من النوع الي اذا راح مطعم بشكل متكرر وحفظه الكاشير ما يحب يتصرف وياه كأنه خويه وبيسلك له لين ما الكاشير يفهمها؛ فهو من النوع الي “أعطيني الطلب وأمشي” مع أنه يعطي الكاشير اكرامية\nيعني إذا باختصر لك باقول عنده ضمير ويحب ينكت وتهكمي وطيب بس غير ودود يعني أحسه من النوع الي اذا شفته في الجامعة ما يبغاك تسلم عليه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537211-bus200", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohammed-al-subaie/172139/11", "user": "user12137", "ts": 1704961081000, "tid": 172139, "pn": 11}}]}', 1704961081000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
